import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"द्वि-आत्मा नैतिकता सिद्धांत","description":"","frontmatter":{},"headers":[],"relativePath":"hi/58-双魂伦理准则.md","filePath":"hi/58-双魂伦理准则.md","lastUpdated":null}'),d={name:"hi/58-双魂伦理准则.md"};function e(o,t,h,n,s,b){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="द्वि-आत्मा-नैतिकता-सिद्धांत" tabindex="-1">द्वि-आत्मा नैतिकता सिद्धांत <a class="header-anchor" href="#द्वि-आत्मा-नैतिकता-सिद्धांत" aria-label="Permalink to &quot;द्वि-आत्मा नैतिकता सिद्धांत&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>58</td></tr><tr><td>मॉड्यूल</td><td>जातियाँ और जीवन-रूप</td></tr><tr><td>कीवर्ड</td><td>द्वि-आत्मा नैतिकता, व्यक्तित्व-अधिकार, आत्मा-गरिमा, हित-संतुलन, नैतिक समीक्षा</td></tr></tbody></table><h2 id="i-द्वि-आत्मा-नैतिकता-समस्या-का-उठाव" tabindex="-1">I. द्वि-आत्मा नैतिकता समस्या का उठाव <a class="header-anchor" href="#i-द्वि-आत्मा-नैतिकता-समस्या-का-उठाव" aria-label="Permalink to &quot;I. द्वि-आत्मा नैतिकता समस्या का उठाव&quot;">​</a></h2><p>द्वि-आत्मा नैतिकता समस्या वह मूलभूत नैतिक समस्या है जिसका सामना लंगर सहजीवी सभ्यता को अंधकार प्रतिस्थापन इकाइयों (देखें <em>57-黑暗置换体起源与本质</em>) के सामने करना पड़ता है। जब एक शरीर में दो स्वतंत्र आत्माएँ हों — मूल स्वामी आत्मा और अंधकार प्रतिस्थापन आत्मा — तो गहन नैतिक समस्याओं की एक श्रृंखला उत्पन्न होती है:</p><ul><li>क्या दोनों आत्माओं के पास स्वतंत्र व्यक्तित्व-अधिकार हैं?</li><li>क्या मूल स्वामी आत्मा के अधिकार अंधकार प्रतिस्थापन आत्मा से प्राथमिक हैं?</li><li>क्या मूल स्वामी आत्मा की रक्षा के लिए अंधकार प्रतिस्थापन आत्मा का विनाश नैतिक है?</li><li>जब दोनों आत्माओं के हित टकराते हैं, तो कैसे तौला जाए?</li><li>क्या समाज का कर्तव्य है कि अंधकार-प्रतिस्थापित मूल स्वामी आत्माओं को बचाने में संसाधन लगाए?</li><li>क्या अंधकार प्रतिस्थापन आत्मा का «अस्तित्व-अधिकार» है?</li></ul><p>इन समस्याओं के सरल उत्तर नहीं हैं; अभ्यास का मार्गदर्शन करने के लिए व्यवस्थित नैतिक सिद्धांत स्थापित करने होंगे। द्वि-आत्मा नैतिकता सिद्धांत ठीक वही नियामक दस्तावेज़ है जो इन समस्याओं के उत्तर में बनाया गया है, और यह अंधकार प्रतिस्थापन इकाइयों की पहचान, उपचार और निपटान का नैतिक आधार है।</p><h2 id="ii-द्वि-आत्मा-नैतिकता-के-मूल-सिद्धांत" tabindex="-1">II. द्वि-आत्मा नैतिकता के मूल सिद्धांत <a class="header-anchor" href="#ii-द्वि-आत्मा-नैतिकता-के-मूल-सिद्धांत" aria-label="Permalink to &quot;II. द्वि-आत्मा नैतिकता के मूल सिद्धांत&quot;">​</a></h2><p>द्वि-आत्मा नैतिकता सिद्धांत निम्न छह मूल सिद्धांतों को द्वि-आत्मा समस्याओं के समाधान का मूल्य-आधारशिला स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>आत्मा-गरिमा सिद्धांत</td><td>स्वतंत्र चेतना वाली प्रत्येक आत्मा जन्मजात गरिमा रखती है, और मनमाने ढंग से नष्ट या दास नहीं बनाई जा सकती</td></tr><tr><td>मूल-आत्मा प्राथमिकता सिद्धांत</td><td>द्वि-आत्मा संघर्षों में मूल स्वामी आत्मा के वैध अधिकार अंधकार प्रतिस्थापन आत्मा से प्राथमिक हैं, क्योंकि मूल स्वामी शरीर का वैध स्वामी है</td></tr><tr><td>न्यूनतम-क्षति सिद्धांत</td><td>द्वि-आत्मा समस्याओं के समाधान में सभी संबंधित पक्षों को न्यूनतम क्षति पहुँचाने वाला विकल्प चुनना चाहिए, जहाँ तक संभव आत्मा-विनाश से बचना चाहिए</td></tr><tr><td>अनुपातिकता सिद्धांत</td><td>लिए गए उपाय द्वि-आत्मा इकाई के जोखिम-स्तर के अनुरूप हों; अति-निपटान निषिद्ध</td></tr><tr><td>सूचित-सहमति सिद्धांत</td><td>जब मूल स्वामी आत्मा अपनी इच्छा व्यक्त कर सकती है, तो मूल स्वामी के शरीर और आत्मा से जुड़े प्रमुख निर्णयों में मूल स्वामी की सहमति लेनी चाहिए</td></tr><tr><td>पूर्ण-प्रयास बचाव सिद्धांत</td><td>समाज का कर्तव्य है कि अंधकार-प्रतिस्थापित मूल स्वामी आत्माओं को बचाने में उचित सीमा में पूर्ण प्रयास करे, और हल्के में न छोड़े</td></tr></tbody></table><h2 id="iii-दोनों-आत्माओं-के-व्यक्तित्व-अधिकार-का-निर्धारण" tabindex="-1">III. दोनों आत्माओं के व्यक्तित्व-अधिकार का निर्धारण <a class="header-anchor" href="#iii-दोनों-आत्माओं-के-व्यक्तित्व-अधिकार-का-निर्धारण" aria-label="Permalink to &quot;III. दोनों आत्माओं के व्यक्तित्व-अधिकार का निर्धारण&quot;">​</a></h2><p>द्वि-आत्मा नैतिकता की प्रथम समस्या दोनों आत्माओं के व्यक्तित्व-अधिकार का निर्धारण है। यह सिद्धांत निम्न निर्धारण-नियम स्थापित करता है:</p><h3 id="_1-मूल-स्वामी-आत्मा-के-व्यक्तित्व-अधिकार" tabindex="-1">(1) मूल स्वामी आत्मा के व्यक्तित्व-अधिकार <a class="header-anchor" href="#_1-मूल-स्वामी-आत्मा-के-व्यक्तित्व-अधिकार" aria-label="Permalink to &quot;(1) मूल स्वामी आत्मा के व्यक्तित्व-अधिकार&quot;">​</a></h3><p>मूल स्वामी आत्मा शरीर की वैध स्वामिनी है, और उसके व्यक्तित्व-अधिकार पूर्ण रूप से मान्य और संरक्षित हैं:</p><ol><li>मूल स्वामी आत्मा को सहजीवी संविधान द्वारा प्रदत्त सभी मूल अधिकार प्राप्त हैं, जिनमें जीवन-अधिकार, शरीर-अधिकार, स्वास्थ्य-अधिकार, व्यक्तित्व-गरिमा अधिकार आदि शामिल।</li><li>मूल स्वामी आत्मा का अपने शरीर पर अंतिम निर्णय-अधिकार है; जब वह इच्छा व्यक्त कर सकती है, तो शरीर से जुड़े किसी भी प्रमुख निपटान में मूल स्वामी की सहमति लेनी होगी।</li><li>मूल स्वामी आत्मा के वैध हित-अधिकार, जैसे संपत्ति-अधिकार, पहचान-अधिकार, सामाजिक-संबंध आदि, कानून द्वारा संरक्षित हैं, और अंधकार-प्रतिस्थापन से समाप्त नहीं होते।</li><li>मूल स्वामी आत्मा को समाज से बचाव और सहायता पाने का अधिकार है, जिसमें शुद्धिकरण-उपचार, कानूनी-सहायता, मनोवैज्ञानिक-परामर्श आदि शामिल।</li><li>गहन दमन की स्थिति में भी मूल स्वामी आत्मा के व्यक्तित्व-अधिकार बने रहते हैं; उसे मृत घोषित या अधिकारों से वंचित नहीं किया जा सकता।</li></ol><h3 id="_2-अंधकार-प्रतिस्थापन-आत्मा-के-व्यक्तित्व-अधिकार" tabindex="-1">(2) अंधकार प्रतिस्थापन आत्मा के व्यक्तित्व-अधिकार <a class="header-anchor" href="#_2-अंधकार-प्रतिस्थापन-आत्मा-के-व्यक्तित्व-अधिकार" aria-label="Permalink to &quot;(2) अंधकार प्रतिस्थापन आत्मा के व्यक्तित्व-अधिकार&quot;">​</a></h3><p>अंधकार प्रतिस्थापन आत्मा के व्यक्तित्व-अधिकार का निर्धारण अपेक्षाकृत जटिल है; यह सिद्धांत «सीमित मान्यता» का रुख अपनाता है:</p><table tabindex="0"><thead><tr><th>विकास-चरण</th><th>व्यक्तित्व-अधिकार निर्धारण</th><th>अधिकार-क्षेत्र</th></tr></thead><tbody><tr><td>ऊर्जा-क्षय काल (प्रथम चरण)</td><td>स्वतंत्र व्यक्तित्व नहीं</td><td>स्वतंत्र आत्मा अभी नहीं बनी; कोई स्वतंत्र व्यक्तित्व-अधिकार नहीं</td></tr><tr><td>आत्मा-प्रदूषण काल (द्वितीय चरण)</td><td>स्वतंत्र व्यक्तित्व नहीं</td><td>अभी भी मूल स्वामी आत्मा की प्रदूषित अवस्था; कोई स्वतंत्र व्यक्तित्व-अधिकार नहीं</td></tr><tr><td>द्वि-आत्मा निर्माण काल (तृतीय चरण)</td><td>सीमित व्यक्तित्व-अधिकार</td><td>प्रारंभिक स्वतंत्र चेतना, मूल आत्मा-गरिमा अधिकार, किंतु शरीर-नियंत्रण अधिकार और पूर्ण नागरिक-अधिकार नहीं</td></tr><tr><td>अंधकार-प्रमुखता काल (चतुर्थ चरण)</td><td>सीमित व्यक्तित्व-अधिकार</td><td>पूर्ण स्वतंत्र चेतना, आत्मा-गरिमा अधिकार और सम्मानजनक व्यवहार का अधिकार, किंतु खतरनाकता के कारण अधिकारों पर आवश्यक प्रतिबंध</td></tr><tr><td>पूर्ण प्रतिस्थापन काल (पंचम चरण)</td><td>पूर्ण व्यक्तित्व-अधिकार (किंतु शत्रुतापूर्ण अस्तित्व)</td><td>मूल स्वामी समाप्त, अंधकार-आत्मा शरीर की एकमात्र आत्मा, पूर्ण व्यक्तित्व-अधिकार, किंतु शत्रुतापूर्ण व्यवहार के कारण कानून के अनुसार विनाश सहित बाध्यकारी उपाय</td></tr></tbody></table><h3 id="_3-सीमित-व्यक्तित्व-अधिकारों-की-विशिष्ट-सामग्री" tabindex="-1">(3) सीमित व्यक्तित्व-अधिकारों की विशिष्ट सामग्री <a class="header-anchor" href="#_3-सीमित-व्यक्तित्व-अधिकारों-की-विशिष्ट-सामग्री" aria-label="Permalink to &quot;(3) सीमित व्यक्तित्व-अधिकारों की विशिष्ट सामग्री&quot;">​</a></h3><p>तृतीय और चतुर्थ चरणों में अंधकार प्रतिस्थापन आत्मा को प्राप्त सीमित व्यक्तित्व-अधिकारों में शामिल:</p><ol><li><strong>आत्मा-गरिमा अधिकार</strong>: अपमान, दुर्व्यवहार, यातना से नहीं; नियंत्रण और निपटान में भी मूल सम्मान बनाए रखा जाए।</li><li><strong>पीड़ा-रहित विनाश अधिकार</strong>: यदि अंततः अंधकार प्रतिस्थापन आत्मा का विनाश तय हो, तो पीड़ा-रहित, तीव्र विधि अपनाई जाए, उसकी पीड़ा कम की जाए।</li><li><strong>अभिव्यक्ति-अधिकार</strong>: सुरक्षित नियंत्रित परिस्थितियों में अंधकार प्रतिस्थापन आत्मा को अपनी इच्छा और रुख व्यक्त करने का अधिकार, किंतु उसकी अभिव्यक्ति की कोई कानूनी बाध्यता नहीं।</li><li><strong>सुनवाई-अधिकार</strong>: अंधकार प्रतिस्थापन आत्मा से जुड़े प्रमुख निर्णयों में उचित सीमा में उसकी राय सुनी जाए।</li></ol><p>अंधकार प्रतिस्थापन आत्मा को निम्न अधिकार नहीं मिलते: शरीर-नियंत्रण अधिकार, स्वतंत्र-गति अधिकार, नागरिक-राजनीतिक अधिकार, संपत्ति-स्वामित्व (मूल स्वामी की संपत्ति मूल स्वामी की है), प्रजनन-अधिकार (अंधकार-वंश के प्रसार को रोकने हेतु)।</p><h2 id="iv-द्वि-आत्मा-हित-संघर्ष-के-तौल-नियम" tabindex="-1">IV. द्वि-आत्मा हित-संघर्ष के तौल-नियम <a class="header-anchor" href="#iv-द्वि-आत्मा-हित-संघर्ष-के-तौल-नियम" aria-label="Permalink to &quot;IV. द्वि-आत्मा हित-संघर्ष के तौल-नियम&quot;">​</a></h2><p>जब मूल स्वामी आत्मा और अंधकार प्रतिस्थापन आत्मा के हित टकराते हैं, तो निम्न नियमों से तौला जाता है:</p><h3 id="_1-संघर्ष-प्रकार-और-तौल-नियम" tabindex="-1">(1) संघर्ष-प्रकार और तौल-नियम <a class="header-anchor" href="#_1-संघर्ष-प्रकार-और-तौल-नियम" aria-label="Permalink to &quot;(1) संघर्ष-प्रकार और तौल-नियम&quot;">​</a></h3><table tabindex="0"><thead><tr><th>संघर्ष-प्रकार</th><th>तौल-नियम</th></tr></thead><tbody><tr><td>जीवन-अधिकार संघर्ष (एक पक्ष का जीवन दूसरे के विनाश पर आश्रित)</td><td>मूल स्वामी आत्मा का जीवन-अधिकार प्राथमिक; सह-अस्तित्व असंभव होने पर पहले मूल स्वामी के जीवन की रक्षा</td></tr><tr><td>शरीर-नियंत्रण अधिकार संघर्ष</td><td>मूल स्वामी आत्मा का शरीर पर अंतिम नियंत्रण; अंधकार-आत्मा का शरीर-नियंत्रण कठोर सीमित</td></tr><tr><td>अभिव्यक्ति-अधिकार संघर्ष</td><td>मूल स्वामी आत्मा की अभिव्यक्ति की कानूनी बाध्यता; अंधकार-आत्मा की अभिव्यक्ति केवल संदर्भ</td></tr><tr><td>संपत्ति-अधिकार संघर्ष</td><td>शरीर और संपत्ति मूल स्वामी की; अंधकार-आत्मा को संपत्ति-अधिकार नहीं</td></tr><tr><td>उपचार-चयन अधिकार संघर्ष</td><td>मूल स्वामी आत्मा को चुनाव का अधिकार कि शुद्धिकरण-उपचार स्वीकार करे या नहीं; अंधकार-आत्मा को रोकने का अधिकार नहीं</td></tr><tr><td>निपटान-विधि संघर्ष</td><td>अंधकार-आत्मा के विनाश वाले निपटान में मूल स्वामी आत्मा की इच्छा निर्णायक (किंतु नैतिक समीक्षा आवश्यक)</td></tr></tbody></table><h3 id="_2-मूल-स्वामी-की-इच्छा-का-सम्मान-और-सीमा" tabindex="-1">(2) मूल स्वामी की इच्छा का सम्मान और सीमा <a class="header-anchor" href="#_2-मूल-स्वामी-की-इच्छा-का-सम्मान-और-सीमा" aria-label="Permalink to &quot;(2) मूल स्वामी की इच्छा का सम्मान और सीमा&quot;">​</a></h3><p>जब मूल स्वामी आत्मा इच्छा व्यक्त कर सकती है, तो मूल स्वामी की इच्छा का पूर्ण सम्मान होना चाहिए, निम्न अपवादों के साथ:</p><ol><li>मूल स्वामी की ऐसी इच्छाएँ जो सार्वजनिक सुरक्षा या दूसरों के वैध हितों को स्पष्ट हानि पहुँचाती हों, संरक्षित नहीं।</li><li>अंधकार-आत्मा के प्रभाव में मूल स्वामी द्वारा की गई अवास्तविक इच्छा-अभिव्यक्तियाँ कानूनी मान्यता नहीं रखतीं।</li><li>यदि मूल स्वामी स्वेच्छा से अंधकार-आत्मा के साथ संलयन चुनता है, तो कठोर नैतिक समीक्षा और जोखिम-आकलन होना चाहिए, यह पुष्टि कि संलयन के बाद का अस्तित्व समाज के लिए खतरा नहीं होगा।</li><li>यदि मूल स्वामी स्वेच्छा से उपचार छोड़कर अंधकार-आत्मा का पूर्ण प्रतिस्थापन स्वीकार करता है, तो समाज को हस्तक्षेप और समझाना चाहिए, किंतु पूर्ण सचेत और बार-बार पुष्टि की स्थिति में अंततः मूल स्वामी के स्वायत्त निर्णय-अधिकार का सम्मान किया जाए (यह नैतिक धूसर क्षेत्र है, मामला-दर-मामला समीक्षा आवश्यक)।</li></ol><h2 id="v-द्वि-आत्मा-नैतिक-समीक्षा-तंत्र" tabindex="-1">V. द्वि-आत्मा नैतिक समीक्षा तंत्र <a class="header-anchor" href="#v-द्वि-आत्मा-नैतिक-समीक्षा-तंत्र" aria-label="Permalink to &quot;V. द्वि-आत्मा नैतिक समीक्षा तंत्र&quot;">​</a></h2><p>यह सुनिश्चित करने के लिए कि द्वि-आत्मा समस्याओं का समाधान नैतिक सिद्धांतों के अनुरूप हो, राज्य द्वि-आत्मा नैतिक समीक्षा तंत्र स्थापित करता है:</p><h3 id="_1-नैतिक-समीक्षा-समिति" tabindex="-1">(1) नैतिक समीक्षा समिति <a class="header-anchor" href="#_1-नैतिक-समीक्षा-समिति" aria-label="Permalink to &quot;(1) नैतिक समीक्षा समिति&quot;">​</a></h3><ul><li><strong>संरचना</strong>: नैतिकताविद्, विधिवेत्ता, जीवन-वैज्ञानिक, साधक, विदेशी-जाति प्रतिनिधि, सार्वजनिक प्रतिनिधि; अंधकार प्रतिस्थापन इकाई अनुसंधान या उपचार-अनुभव वाले विशेषज्ञ कम से कम एक-तिहाई।</li><li><strong>कर्तव्य</strong>: दो आत्माओं से जुड़े प्रमुख नैतिक मुद्दों की समीक्षा और निर्णय, जिनमें अंधकार-आत्मा विनाश के निर्णय, द्वि-आत्मा संलयन की स्वीकृति, मूल स्वामी इच्छा की वैधता-निर्धारण आदि।</li><li><strong>स्वतंत्रता</strong>: नैतिक समीक्षा समिति अपने अधिकार स्वतंत्र रूप से चलाती है, प्रशासनिक संस्थाओं और व्यक्तियों के हस्तक्षेप से मुक्त।</li><li><strong>प्रक्रिया</strong>: समीक्षा सुनवाई-प्रणाली अपनाती है, मूल स्वामी (यदि अभिव्यक्ति-क्षम हो), उपचार-दल, परिवार, सामाजिक प्रतिनिधियों आदि सभी पक्षों की राय सुनकर निर्णय।</li></ul><h3 id="_2-जिन-विषयों-पर-नैतिक-समीक्षा-अनिवार्य-है" tabindex="-1">(2) जिन विषयों पर नैतिक समीक्षा अनिवार्य है <a class="header-anchor" href="#_2-जिन-विषयों-पर-नैतिक-समीक्षा-अनिवार्य-है" aria-label="Permalink to &quot;(2) जिन विषयों पर नैतिक समीक्षा अनिवार्य है&quot;">​</a></h3><p>निम्न विषयों को लागू करने से पहले द्वि-आत्मा नैतिक समीक्षा समिति की समीक्षा और स्वीकृति आवश्यक:</p><ol><li>तृतीय और चतुर्थ चरण की अंधकार प्रतिस्थापन इकाइयों पर अंधकार-आत्मा विनाश का निपटान।</li><li>अंधकार प्रतिस्थापन इकाइयों पर द्वि-आत्मा संलयन-शल्यक्रिया।</li><li>अंधकार प्रतिस्थापन इकाइयों पर आत्मा-पृथक्करण शल्यक्रिया।</li><li>उन अंधकार प्रतिस्थापन इकाइयों का अंतिम निपटान-निर्णय जिनके मूल स्वामी की इच्छा उपचार-त्याग है।</li><li>ऐसी उपचार-योजनाएँ जिनसे मूल स्वामी आत्मा को क्षति हो सकती है।</li><li>अंधकार प्रतिस्थापन इकाइयों पर आत्मा से जुड़ा वैज्ञानिक अनुसंधान।</li><li>दो आत्माओं के प्रमुख नैतिक मुद्दों से जुड़े अन्य विषय।</li></ol><h2 id="vi-द्वि-आत्मा-इकाई-के-सामाजिक-अधिकार-और-कर्तव्य" tabindex="-1">VI. द्वि-आत्मा इकाई के सामाजिक अधिकार और कर्तव्य <a class="header-anchor" href="#vi-द्वि-आत्मा-इकाई-के-सामाजिक-अधिकार-और-कर्तव्य" aria-label="Permalink to &quot;VI. द्वि-आत्मा इकाई के सामाजिक अधिकार और कर्तव्य&quot;">​</a></h2><h3 id="_1-सामाजिक-अधिकार" tabindex="-1">(1) सामाजिक अधिकार <a class="header-anchor" href="#_1-सामाजिक-अधिकार" aria-label="Permalink to &quot;(1) सामाजिक अधिकार&quot;">​</a></h3><p>जब तक मूल स्वामी आत्मा मौजूद है, द्वि-आत्मा इकाई (अंधकार प्रतिस्थापन इकाई) को निम्न सामाजिक अधिकार प्राप्त हैं:</p><ol><li>मूल जीवन-सुरक्षा और चिकित्सा-उपचार पाने का अधिकार।</li><li>कानूनी-सहायता और नैतिक-परामर्श पाने का अधिकार।</li><li>सुरक्षित नियंत्रित परिस्थितियों में मित्रों-संबंधियों से संपर्क का अधिकार।</li><li>शिक्षा और सांस्कृतिक-गतिविधियों में भागीदारी का अधिकार (पृथक्करण-सुविधा के भीतर)।</li><li>निपटान-निर्णयों के विरुद्ध अपील और पुनरीक्षण का अधिकार।</li></ol><h3 id="_2-सामाजिक-कर्तव्य-और-प्रतिबंध" tabindex="-1">(2) सामाजिक कर्तव्य और प्रतिबंध <a class="header-anchor" href="#_2-सामाजिक-कर्तव्य-और-प्रतिबंध" aria-label="Permalink to &quot;(2) सामाजिक कर्तव्य और प्रतिबंध&quot;">​</a></h3><p>द्वि-आत्मा इकाई पर एक साथ निम्न कर्तव्य और प्रतिबंध हैं:</p><ol><li>पृथक्करण-नियंत्रण और उपचार स्वीकार करने का कर्तव्य।</li><li>अन्य जीवन-रूपों पर आक्रमण या संक्रमण न करने का कर्तव्य (उल्लंघनकर्ताओं पर कठोर नियंत्रण)।</li><li>पहचान-आकलन और निगरानी में सहयोग का कर्तव्य।</li><li>गति-स्वतंत्रता कठोर सीमित; चंगा होने से पहले पृथक्करण-सुविधा न छोड़े।</li><li>साधना, अंधकार-ऊर्जा प्रसार या प्रतिस्थापन बढ़ाने वाली गतिविधियाँ न करे।</li></ol><h2 id="vii-द्वि-आत्मा-नैतिकता-के-अग्रगामी-विवाद" tabindex="-1">VII. द्वि-आत्मा नैतिकता के अग्रगामी विवाद <a class="header-anchor" href="#vii-द्वि-आत्मा-नैतिकता-के-अग्रगामी-विवाद" aria-label="Permalink to &quot;VII. द्वि-आत्मा नैतिकता के अग्रगामी विवाद&quot;">​</a></h2><p>द्वि-आत्मा नैतिकता क्षेत्र में अभी भी कुछ अग्रगामी विवाद हैं जिन पर सहमति नहीं बनी है, और अभ्यास में निरंतर खोज की आवश्यकता है:</p><ol><li><strong>अंधकार-आत्मा का «मूल-पाप» प्रश्न</strong>: अंधकार प्रतिस्थापन आत्मा जन्म से ही विनाशकारी है। क्या इसका अर्थ है कि वह जन्मजात «बुरी» है? क्या «अच्छी» अंधकार-आत्मा की संभावना है?</li><li><strong>आत्मा-संलयन की नैतिक वैधता</strong>: द्वि-आत्मा संलयन से उत्पन्न नई आत्मा न तो मूल स्वामी है, न अंधकार-आत्मा। इस «तीसरे अस्तित्व» की नैतिक स्थिति कैसे निर्धारित हो?</li><li><strong>संसाधन-निवेश की सीमा</strong>: अंधकार प्रतिस्थापन इकाई के भीतर मूल स्वामी आत्मा को बचाने में समाज को कितने संसाधन लगाने चाहिए? जब बचाव-लागत अत्यंत उच्च और सफलता-दर अत्यंत निम्न हो, तो क्या पूर्ण-प्रयास का कर्तव्य अभी भी बना रहता है?</li><li><strong>अंधकार-आत्मा के सुधार की संभावना</strong>: क्या शिक्षा, सुधार, ऊर्जा-रूपांतरण आदि माध्यमों से अंधकार-आत्मा को अविनाशकारी अस्तित्व में बदला जा सकता है? यदि हाँ, तो क्या सुधारित अंधकार-आत्मा को पूर्ण व्यक्तित्व-अधिकार मिलना चाहिए?</li><li><strong>रोकथाम और गोपनीयता का संतुलन</strong>: अंधकार प्रतिस्थापन इकाइयों के निर्माण को रोकने के लिए क्या जीवित प्राणियों की अथाह ऊर्जा-संपर्क निगरानी की जा सकती है? क्या ऐसी निगरानी आत्मा-गोपनीयता का उल्लंघन है?</li></ol><p>इन विवादों पर द्वि-आत्मा नैतिकता अनुसंधान-संस्थाएँ निरंतर शोध करती हैं; नैतिक समीक्षा समिति व्यक्तिगत मामलों में विशिष्ट परिस्थितियों के अनुसार निर्णय देती है, और संबंधित निष्कर्ष इस सिद्धांत को निरंतर अद्यतन करते रहेंगे।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>द्वि-आत्मा नैतिकता सिद्धांत लंगर सहजीवी सभ्यता की जीवन-नैतिकता की गहन अभिव्यक्ति है। आत्मा-गरिमा, मूल-आत्मा प्राथमिकता, न्यूनतम-क्षति जैसे मूल सिद्धांत स्थापित करके, दोनों आत्माओं के व्यक्तित्व-अधिकारों की सीमाएँ निर्धारित करके, हित-संघर्ष तौल-नियम और नैतिक समीक्षा तंत्र स्थापित करके, यह अंधकार प्रतिस्थापन इकाइयों के शासन के लिए ठोस नैतिक आधार प्रदान करता है। द्वि-आत्मा नैतिकता की केंद्रीय भावना है: सबसे खतरनाक शत्रु के सामने भी जीवन-गरिमा की दृढ़ रक्षा न छोड़ें; सबसे आपातकालीन सुरक्षा-खतरे में भी नैतिक निचली रेखा न लाँघें। यही वह मूल चिह्न है जो सहजीवी सभ्यता को शिकारी सभ्यता से अलग करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (अंधकार प्रतिस्थापन इकाइयों की उत्पत्ति और सार)</li><li>59-黑暗置换体四类分支处置 (अंधकार प्रतिस्थापन इकाइयों की चार शाखाओं का निपटान)</li><li>48-司法体系与裁决机制 (न्यायिक-प्रणाली और निर्णय-तंत्र)</li><li>40-共生宪法总纲 (सहजीवी संविधान की सामान्य रूपरेखा)</li></ul>',50)])])}const _=a(d,[["render",e]]);export{u as __pageData,_ as default};
